            unique += b > 0 ? 1 : 0;
        return unique;
    }

    // return 1 / (b1!b2!b3!...bn!) 
    private double permFake(int[] balls) {
        double ret = 1.0;
        for (int b: balls)
            ret /= factorial(b);
        return ret;
    }

    private int factorial(int n){
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
